[MethodImpl(MethodImplOptions.NoInlining)]
static void Benchmark(string name, Action action)
{
    // Warmup
    for (int i = 0; i < 1000; i++) action();

    // Find iteration count that takes ~2 seconds
    int iterations = 1000;
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < iterations; i++) action();
    sw.Stop();

    // Scale to ~2 seconds
    double targetMs = 2000;
    iterations = (int)(iterations * targetMs / sw.Elapsed.TotalMilliseconds);
    if (iterations < 1000) iterations = 1000;

    // Actual measurement - take best of 3 runs
    double bestNs = double.MaxValue;
    for (int run = 0; run < 3; run++)
    {
        sw.Restart();
        for (int i = 0; i < iterations; i++) action();
        sw.Stop();
        double ns = sw.Elapsed.TotalNanoseconds / iterations;
        if (ns < bestNs) bestNs = ns;
    }

    Console.WriteLine($"{name,-25} {bestNs,12:F2} {iterations,12:N0}");
}

